# -*- coding: utf-8 -*-
# Extras: glossary, project gallery specs, cheat sheets, SVG diagrams.

# ---------------- GLOSSARY (~150 terms) ----------------
GLOSSARY = [
    ("attribute", "A name/value pair inside an opening tag (href, class, src…) that configures the element."),
    ("autofill", "Browser feature that pre-fills form controls (name, email, card) from saved data; steered by the autocomplete attribute."),
    ("backdrop", "The dimmed layer behind an open <dialog> (showModal) or a glassmorphism surface (backdrop-filter)."),
    ("baseline", "The invisible line on which text sits; inline elements align to the text baseline by default."),
    ("block formatting context", "A layout container where children are laid out block-wise, isolated from the outside (created by BFC triggers like overflow:hidden)."),
    ("border-box", "Box model where width includes padding + border (the * { box-sizing: border-box; } reset)."),
    ("browser engine", "The rendering core (Blink, WebKit, Gecko) that parses HTML, computes style, and paints pixels."),
    ("cascade", "The algorithm that resolves conflicting CSS rules using origin, layer, specificity, and source order."),
    ("checkbox", "A multi-choice <input type=\"checkbox\"> control (0..n selected)."),
    ("class selector", "The .name selector matching an element's class list — the backbone of styling."),
    ("clip-path", "CSS that clips an element to a shape (circle, polygon, path) — non-rectangular UI."),
    ("color scheme", "The declared light/dark support (color-scheme) that themes native controls and canvases."),
    ("combinator", "Selector operators: space (descendant), > (child), + (adjacent sibling), ~ (general sibling)."),
    ("component", "A self-contained UI piece (card, modal) with its own markup, styles, and behavior."),
    ("computed style", "The final values of a property after the cascade + inheritance (getComputedStyle)."),
    ("contain", "A CSS performance hint limiting an element's side effects to its subtree."),
    ("content box", "The innermost rectangle of the box model — the area the width/height describe (content-box)."),
    ("critical rendering path", "HTML parse → DOM → CSS parse → CSSOM → render tree → layout → paint; the steps to a painted page."),
    ("custom property", "A CSS variable (--name) that can hold any value and be used via var()."),
    ("datalist", "The <datalist> suggestions source linked to an <input> via list=…"),
    ("DOM", "Document Object Model — the live tree of elements the browser builds from HTML."),
    ("drop cap", "An enlarged first letter of a paragraph (::first-letter / initial-letter)."),
    ("edge-to-edge", "Full-viewport layout where content reaches the screen edges (modern mobile design)."),
    ("ellipsis truncation", "The white-space:nowrap + overflow:hidden + text-overflow:ellipsis one-line cut."),
    ("embed", "The <embed> element for external plugin resources (legacy)."),
    ("fieldset", "The form-group element that bundles controls under a <legend>."),
    ("figure", "The <figure> + <figcaption> pair for self-contained media with captions."),
    ("flex basis", "The starting main-size of a flex item before grow/shrink (flex-basis)."),
    ("flex container", "An element with display:flex; its children become flex items on the main axis."),
    ("flex item", "A direct child of a flex container; sized by grow/shrink/basis and aligned with gap."),
    ("focus ring", "The visible outline for keyboard focus — the a11y must (focus-visible)."),
    ("fragment", "The part of a URL after # (e.g. #section) that scrolls to / targets an element."),
    ("grid area", "A named rectangle in grid-template-areas that items claim via grid-area."),
    ("grid container", "An element with display:grid; children become grid items placed on tracks."),
    ("grid track", "A single row or column of the grid, sized by fr/minmax/lengths."),
    ("heading level", "h1–h6 — the document outline; use in order, style with CSS."),
    ("iframe", "An embedded browsing context (separate document) inside the page."),
    ("inert", "A global attribute disabling interactivity and a11y for a subtree (grayed out)."),
    ("inline element", "An element flowing with text (span, a) — width/height don't apply."),
    ("intersection observer", "JS API watching element visibility — the scroll-animation and lazy-load workhorse."),
    ("intrinsic size", "An element's natural size from its content (image pixels, text lines)."),
    ("JSON-LD", "Structured data in <script type=\"application/ld+json\"> for rich search results."),
    ("keyframes", "The @keyframes blocks defining an animation's from/to (and % ) frames."),
    ("label", "The form control caption — clickable and screen-reader announced (<label>)."),
    ("layout shift", "Visible element movement (CLS metric); prevented by reserving dimensions (aspect-ratio)."),
    ("landmark", "A structural region (header, nav, main, aside, footer) assistive tech jumps between."),
    ("lazy loading", "Deferring fetches until near the viewport (loading=\"lazy\", srcset tricks)."),
    ("legend", "The caption of a <fieldset>; must be its first child."),
    ("line box", "The box around each line of text; its height = line-height."),
    ("main axis", "The flex direction items are laid out along (row → horizontal)."),
    ("mark", "The <mark> highlight element (search-result marking)."),
    ("media query", "An @media condition on viewport/feature — the responsive engine."),
    ("minmax()", "Grid sizing: a track between a minimum and maximum (minmax(200px, 1fr))."),
    ("mix-blend-mode", "How an element's pixels composite with the backdrop (multiply, screen…)."),
    ("monospace font", "A font where every glyph has equal width (code, logs)."),
    ("multicol", "The column-* properties for multi-column text layouts (magazine style)."),
    ("named area", "A grid-template-areas name (\"hd hd\") claimed by grid-area: hd."),
    ("nav landmark", "The <nav> element marking major navigation link groups."),
    ("open-type font", "An OFL-licensed font family — free to self-host (Inter, Roboto, Source Sans)."),
    ("outline", "A non-layout line outside the border (focus rings) — unlike border it doesn't push content."),
    ("overflow hidden", "Clipping an element's content (also a BFC trigger and old clearfix)."),
    ("page object model", "The CSSOM — the styled rule tree paired with the DOM."),
    ("placeholder", "Hint text inside empty inputs (not a label — a11y caveat)."),
    ("pointer events", "Mouse/touch hit testing; pointer-events:none lets clicks pass through."),
    ("prefers-color-scheme", "The media query matching the user's OS light/dark preference."),
    ("prefers-reduced-motion", "The media query for users who want less animation — respect it."),
    ("pseudo-class", "A state selector (:hover, :focus, :nth-child) matching conditions, not markup."),
    ("pseudo-element", "Generated content/box (::before, ::after, ::marker) that isn't in the DOM."),
    ("radio group", "<input type=\"radio\"> elements sharing a name — exactly one checked."),
    ("reflow (re-layout)", "Recomputing geometry after a layout-affecting change — expensive at scale."),
    ("repaint", "Redrawing pixels without layout (opacity, transform changes — cheap)."),
    ("rem", "Root-relative length unit: × the <html> font-size (16px default)."),
    ("render tree", "The visible subtree the browser paints (DOM + style, invisible nodes removed)."),
    ("responsive design", "Layouts that adapt to any viewport (fluid units, grid/flex, media queries)."),
    ("root element", "The <html> element — the top of the DOM; rem's reference point."),
    ("RTL", "Right-to-left writing direction (Arabic, Hebrew) — dir=rtl, logical properties."),
    ("sanitization", "Cleaning untrusted input before it touches the DOM (XSS defense)."),
    ("scope attribute", "The th attribute declaring whether it labels a column or row (a11y)."),
    ("scroll-driven animation", "CSS animations linked to scroll position (animation-timeline: scroll())."),
    ("scroll snap", "Scroll containers that land on aligned points (carousels without JS)."),
    ("scrollbar", "The viewport edge control; styled via scrollbar-color/width + ::-webkit-scrollbar."),
    ("scrolling container", "An element that scrolls its content (overflow:auto/scroll) — the snap anchor."),
    ("semantic HTML", "Choosing elements for their meaning (article, nav, main) — a11y + SEO."),
    ("shadow DOM", "An isolated DOM tree inside an element (Web Components) with its own styles."),
    ("shorthand property", "One declaration for several longhands (margin, font, background)."),
    ("sibling combinator", "+ (next) and ~ (all following) — the pure-CSS toggle glue."),
    ("slotted content", "Light-DOM children projected into a <slot> in shadow DOM."),
    ("snap point", "The alignment position a scrolling container stops at (scroll-snap-align)."),
    ("source order", "The order CSS/HTML appears — the last tie-breaker of the cascade."),
    ("srcset", "The image candidate list (URLs + width/descriptor) the browser chooses from."),
    ("stacking context", "A layering island (position+z-index, opacity<1, transform) — z-index can't escape it."),
    ("sticky footer", "The flex/grid layout that pins a footer to the viewport bottom on short pages."),
    ("sticky header", "position:sticky; top:0 — the header that stays on scroll."),
    ("string set", "A space-separated attribute list (class, rel, role)."),
    ("style cascade", "The full pipeline deciding a property's final value (specificity + order)."),
    ("subgrid", "Nested grids that align tracks with the parent grid (grid-template-rows: subgrid)."),
    ("table caption", "The <caption> title of a table (first child)."),
    ("th scope", "See scope attribute — the accessibility anchor of tables."),
    ("thead", "The header-row group of a table; repeats on each printed page."),
    ("token", "A single word in a space-separated attribute (rel, part, class)."),
    ("track", "A <track> media text (captions/subtitles) or a grid track (row/column)."),
    ("transform origin", "The rotation/scaling pivot point (transform-origin)."),
    ("typographic scale", "A harmonious font-size system (e.g. 1.25 ratio: 14→16→20→25)."),
    ("underlay", "A layer behind content (background effects, glows)."),
    ("universal selector", "* — every element; the reset's starting point."),
    ("valid HTML", "Markup that parses per the spec (validators, browsers' error recovery)."),
    ("variable font", "One file, a range of weights/widths (font-variation-settings axes)."),
    ("view-box", "The SVG coordinate system the drawing scales into."),
    ("viewport", "The visible area of the page (the device's screen region showing the page)."),
    ("vtt", "WebVTT — the text track format for <track> captions/subtitles."),
    ("web component", "A custom element + shadow DOM + template — a reusable encapsulated widget."),
    ("webfont", "A font served over the web (@font-face) — woff2 preferred."),
    ("wbr", "The word-break opportunity element for long URLs/words."),
    ("web vitals", "The Core Web Vitals: LCP (loading), CLS (stability), INP (interaction)."),
    ("will-change", "A layer-promotion hint for upcoming animations — use sparingly."),
    ("word-break", "Where long words may break (CJK & overflow control)."),
    ("writing mode", "The text flow direction (horizontal-tb, vertical-rl) — CJK layouts."),
    ("x-height", "The height of lowercase letters (no ascenders) — an ex/typography unit."),
    ("XML", "The extensible markup language HTML descended from (XHTML era)."),
    ("XSS", "Cross-Site Scripting — injecting script via unsanitized input."),
    ("z-index", "Stacking order for positioned elements (higher paints on top)."),
    ("zebra striping", "Alternating row backgrounds: tr:nth-child(even) — table readability."),
    ("zoom units", "The vw/vh viewport length family (1vw = 1% of viewport width)."),
    ("0 / 100vh mobile bug", "Why 100vh jumps with the mobile browser UI — use dvh/svh/lvh."),
]

